            ) : (
                <NavigationButton
                    label="Next"
                    action={ACTION_NEXT}
                    icon={NextIcon}
                    renderIcon={iconNext}
                    style={styles.navigationNext}
                    disabled={nextDisabled}
                    onClick={next}
                />
